// PROGRAM 1: ARRAY IMPLEMENTATION
#include <iostream>
#include <string>
using namespace std;

struct Patient {
    int id; string name; int waitTime; string type; // Consulting, Treatment, ER
};

class PatientArray {
    Patient data[3000]; int count = 0;
public:
    void add(int id, string n, int w, string t) {
        if (count < 3000) data[count++] = {id, n, w, t};
    }
    void bubbleSort() {
        for (int i = 0; i < count - 1; i++)
            for (int j = 0; j < count - i - 1; j++)
                if (data[j].waitTime > data[j+1].waitTime) swap(data[j], data[j+1]);
    }
    void search(int id) {
        for (int i = 0; i < count; i++) 
            if (data[i].id == id) { cout << "Found: " << data[i].name << endl; return; }
        cout << "Not found";
    }
};

// PROGRAM 2: LINKED LIST IMPLEMENTATION
#include <iostream>
#include <string>
using namespace std;

struct Node {
    int id; string name; int waitTime; string type;
    Node* next;
};

class PatientList {
    Node* head = nullptr;
public:
    void insert(int id, string n, int w, string t) {
        Node* newNode = new Node{id, n, w, t, head};
        head = newNode;
    }
    void display() {
        Node* temp = head;
        while(temp) {
            cout << temp->id << " | " << temp->name << " | " << temp->waitTime << endl;
            temp = temp->next;
        }
    }
    void search(int id) {
        Node* temp = head;
        while(temp) {
            if(temp->id == id) { cout << "Found: " << temp->name << endl; return; }
            temp = temp->next;
        }
    }
};

